    {
        int N = tablero1.GetLength(1);
        List<List<(int, int)>> gemLines = new List<List<(int, int)>>();

        for (int i = 0; i < tablero1.GetLength(0); i++)
        {
            for (int j = 0; j < N - 2; j++)
            {
                int count = 1;
                for (int k = j + 1; k < N; k++)
                {
                    if (tablero1[i, k] != tablero1[i, j])
                    {
                        break;
                    }

                    count++;
                }

                if (count >= 3)
                {
                    List<(int, int)> gemLine = new List<(int, int)>();
                    for (int l = j; l < j + count; l++)
                    {
                        gemLine.Add((i, l));
                    }

                    gemLines.Add(gemLine);
                    j += count - 1;
                }
            }
        }

        List<(int, int)> gemList = new List<(int, int)>();
        foreach (List<(int, int)> line in gemLines)
        {
            gemList.AddRange(line);
        }

        return gemList;
    }

