import React, { useState } from 'react';
import { Box, IconButton, Menu, MenuItem } from '@mui/material';
import TranslateIcon from '@mui/icons-material/Translate';

interface Language {
    value: string;
    label: string;
}

const LanguageSwitcher: React.FC = () => {
    const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
    //   const [selectedLanguage, setSelectedLanguage] = useState<Language | null>(null);
    const languages: Language[] = [
        { value: '', label: 'Русский' },
        { value: '/ru/en', label: 'English' },
    ];

    const handleLanguageClick = (event: React.MouseEvent<HTMLButtonElement>) => {
        setAnchorEl(event.currentTarget);
    };

    const handleLanguageClose = (language: Language) => {
        setAnchorEl(null);
        // setSelectedLanguage(language);
        setCookie(language.value);
    };

    const setCookie = (cookieValue: string) => {
        document.cookie = `googtrans=${cookieValue}`;
        window.location.reload();
    };

    return (
        <div>

            <Box>
                <div>
                    <IconButton onClick={handleLanguageClick} size="large" color="inherit">
                            <TranslateIcon />
                    </IconButton>
                </div>
                <div>
                    <Menu
                        anchorEl={anchorEl}
                        open={Boolean(anchorEl)}
                        onClose={() => setAnchorEl(null)}
                    >
                        <div>
                            {languages.map((language) => (
                                <MenuItem key={language.value} onClick={() => handleLanguageClose(language)}>
