	// Return the result of the expression
	return $1->number;
}
          | STRING {
	printf("Expression: %s\n", $1->string);
	// Return the result
	return $1->string;
}
          | expression '+' expression {
	printf("Addition: %d + %d\n", $1, $3);
	// Add the two operands
	return $1 + $3;
}         %prec '*'
