const KLineChart: React.FC<KLineChartProps> = React.memo(({symbol, interval}) => {
  const ref = useRef<HTMLDivElement>(null);
  const [chart, setChart] = useState<Chart|null>(null);
  const [candlesticks, setCandlesticks] = useState<KLineData[]>([]);
  const [kline, setKline] = useState<KLineData>();
  const price = useSelector((state: AppState) => state);
  const [waiting, setWaiting] = useState(false);
  const {enqueueSnackbar} = useSnackbar();
  //   binanceSymbolSlice
  // sseOpenOrderSlice
  // sseNewTradeSlice
  // sseBalanceUpdateSlice
  // ssePositionUpdateSlice
  const {futuresSubscribe, futuresUnsubscribe, futuresReadyState,
    spotSubscribe,
    spotUnsubscribe, spotReadyState} = useBinanceWsProvider();

  // console.log(spotSubscribe(symbol));
  // console.log(price);
  // console.log(futuresReadyState);
  // console.log(symbol,price);

  const onWindowResize = () => chart?.resize();

  useEffect(() => {
    window.addEventListener("resize", onWindowResize);
    onWindowResize();
    window.devicePixelRatio = 3;

    return () => {
      window.removeEventListener("resize", onWindowResize);
    };
  }, [ref]);

  // useEffect(() => {
  //   console.log();

  //   spotSubscribe(symbol);

  //   return () => spotSubscribe(symbol);
  // }, []);

  useEffect(() => {
    if (chart) {
      chart.applyNewData(candlesticks);
    }
  }, [chart, candlesticks]);

  useEffect(() => {
    if (ref && ref.current && !chart) {
      const kLineChart = init(ref.current, {styles: chartStyles});
      setChart(kLineChart);
    }
  }, [ref, chart]);

  useEffect(() => {
    if (kline && chart) {
      chart.updateData(kline);
    }
  }, [kline, chart]);

  const connectToWs = () => {
    const webSocket = new WebSocket(
      `wss://fstream.binance.com/ws/${symbol}@kline_${interval}`
    );

    webSocket.onmessage = (message) => {
      const data = JSON.parse(message.data);
      const candleData = data.k;
      const newCandel = {
        timestamp: candleData.t,
        open: parseFloat(candleData.o),
        high: parseFloat(candleData.h),
        low: parseFloat(candleData.l),
        close: parseFloat(candleData.c),
        volume: parseFloat(candleData.v),
      };
      setKline(newCandel);
    };
  };

  const fetchCandlesticks = () => {
    fetchSymbolsKlines(symbol, interval)?.then((response) => {
      setCandlesticks(
        response.data.map((candlestick: Array<number | string>) => {
          return {
            timestamp: dayjs.utc(candlestick[0]).valueOf(),
            open: parseFloat(candlestick[1].toString()),
            high: parseFloat(candlestick[2].toString()),
            low: parseFloat(candlestick[3].toString()),
            close: parseFloat(candlestick[4].toString()),
            volume: parseFloat(candlestick[5].toString()),
          };
        })
      );

      connectToWs();
    });
  };

  useEffect(() => {
    fetchCandlesticks();
  }, []);

  useEffect(() => {
    if (candlesticks.length === 0) return;
    chart?.subscribeAction(ActionType.OnScroll, onScrollbarPositionChanged);

    return (() => {
      chart?.unsubscribeAction(ActionType.OnScroll, onScrollbarPositionChanged);
    });
  }, [chart, candlesticks]);

  let isLoading = false;

  let onScrollbarPositionChanged = () => {
    const dataList = chart?.getDataList();
    const from = chart?.getVisibleRange().realFrom;

    if (!dataList || isLoading) return;

    if (from === 0) {
      let endTime = dataList[0].timestamp;
      let prevTime: number | null = null;
      isLoading = true;
      setWaiting(true);

      fetchSymbolsKlines(symbol, interval, undefined, endTime)?.then((data) => {
        const newCandles = data.data?.map((item: any[]) => ({
          timestamp: item[0],
          open: item[1],
          high: item[2],
          low: item[3],
          close: item[4],
          volume: item[5],
        }));

        if (!newCandles || newCandles.length === 0) {
          return;
        } else {
          if (prevTime === newCandles[newCandles.length - 1].timestamp) {
            isLoading = false;
            setWaiting(false);

            return;
          }

          if (newCandles[newCandles.length - 1].timestamp === dataList[dataList.length - 1].timestamp) {
            isLoading = false;
            setWaiting(false);

            return;
          }

          prevTime = newCandles[newCandles.length - 1].timestamp;
          chart?.applyMoreData(newCandles);
        }

        isLoading = false;
        setWaiting(false);
      })
        .catch((error) => {
          enqueueSnackbar(error.message, {variant: "error"});
          isLoading = false; 
          setWaiting(false);
        });
    }
  };

  return (
    <>
      {
        waiting ? (
          <CircularProgress
            style={{position: "absolute", marginLeft: "1rem"}}
            color="inherit"
            size={32}
          />
        ) : (<></>)
      }
      <Box
        ref={ref}
        id={`chart-${symbol}`}
        style={{width: "100%", height: "calc(100% - 50px)"}}
      />
    </>
  );
});
