public class UserDAO {

private SQLiteOpenHelper dbHelper;
private SQLiteDatabase database;

public static final String TABLE_USERS = “users_table”;
public static final String COLUMN_ID = “id”;
public static final String COLUMN_NAME = “name”;
public static final String COLUMN_EMAIL = “email”;
public static final String COLUMN_PASSWORD = “password”;

public static final String CREATE_USERS_TABLE = “CREATE TABLE ” + TABLE_USERS + ” (” +
COLUMN_ID + ” INTEGER PRIMARY KEY AUTOINCREMENT, ” +
COLUMN_NAME + ” TEXT NOT NULL, ” +
COLUMN_EMAIL + ” TEXT NOT NULL UNIQUE, ” +
COLUMN_PASSWORD + ” TEXT NOT NULL);”;

public UserDAO(Context context) {
dbHelper = new UserDatabaseHelper(context);
}

public void open() {
database = dbHelper.getWritableDatabase();
}

public void close() {
dbHelper.close();
}

public long register(String name, String email, String password) {
ContentValues values = new ContentValues();
values.put(COLUMN_NAME, name);
values.put(COLUMN_EMAIL, email);
values.put(COLUMN_PASSWORD, password);

long rowID = database.insert(TABLE_USERS, null, values);
return rowID;
}

public boolean login(String email, String password) {
String selection = COLUMN_EMAIL + “= ? AND ” + COLUMN_PASSWORD + “= ?";
String[] selectionArgs = { email, password };

Cursor cursor = database.query(TABLE_USERS, null, selection, selectionArgs,
null, null, null);

if (cursor.getCount() > 0) {
cursor.moveToFirst();
String dbEmail = cursor.getString(cursor.getColumnIndex(COLUMN_EMAIL));
String dbPassword = cursor.getString(cursor.getColumnIndex(COLUMN_PASSWORD));
if (dbEmail.equals(email) && dbPassword.equals(password)) {
return true;
} else {
return false;
}
} else {
return false;
}
}

public List<User> getAllUsers() {
List<User> users = new ArrayList<User>();

Cursor cursor = database.rawQuery(“SELECT * FROM ” + TABLE_USERS, null);

cursor.moveToFirst();
while (!cursor.isAfterLast()) {
User user = new User();
user.setId(cursor.getLong(cursor.getColumnIndex(COLUMN_ID)));
user.setName(cursor.getString(cursor.getColumnIndex(COLUMN_NAME)));
user.setEmail(cursor.getString(cursor.getColumnIndex(COLUMN_EMAIL)));
user.setPassword(cursor.getString(cursor.getColumnIndex(COLUMN_PASSWORD)));

users.add(user);
cursor.moveToNext();
}
cursor.close();

return users;
}

private class UserDatabaseHelper extends SQLiteOpenHelper {

public UserDatabaseHelper(Context context) {
super(context, “userDatabase.db”, null, 1);
}

@Override
public void onCreate(SQLiteDatabase db) {
db.execSQL(CREATE_USERS_TABLE);
}

@Override
public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
db.execSQL(“DROP TABLE IF EXISTS ” + TABLE_USERS);
onCreate(db);
}
}
}

